from research_helpers import *
a=ev('https://www.foundationmedicine.com/our-solutions','Current named clinical portfolio. Four profiling tests developed by Foundation; Germline/More and PGx by Fulgent, MRD by SAGA. LDT availability not FDA approval.')
b=ev('https://www.foundationmedicine.com/solution/ihc-testing','Ten named immunohistochemical target/panel offerings; tissue-specific ordering bundles not separate assays.')
c=ev('https://www.foundationmedicine.com/solution/foundationone-germline','Germline and Germline More are distinct reference-lab panels.')
d=ev('https://www.foundationmedicine.com/solution/foundationone-mrd','Current branded MRD offering performed by SAGA, not Foundation-owned assay development.')
products=[]
for name,desc in [('FoundationOne CDx','Tissue genomic profiling test.'),('FoundationOne Liquid CDx','Blood genomic profiling test.'),('FoundationOne Heme','Haematologic cancer DNA/RNA profiling test.'),('FoundationOne RNA','Solid-tumour fusion/rearrangement RNA test.')]:products.append(p(name,desc,a,'commercial',typ='product',sub='diagnostics'))
for name,desc,src in [('FoundationOne Germline','Reference-lab hereditary cancer panel.',c),('FoundationOne Germline More','Expanded reference-lab hereditary cancer panel.',c),('FoundationOne PGx','Reference-lab pharmacogenetic test.',a),('FoundationOne MRD','Partner-performed molecular residual-disease test.',d)]:products.append(p(name,desc,src,'commercial',roles=['commercial_partner'],typ='product',sub='diagnostics'))
for target in ['CLAUDIN18','DLL3','ER','FOLR1','HER2','MET','MMR','PD-L1','PR','PTEN']:products.append(p('Foundation Medicine '+target+' IHC test','Immunohistochemical target/panel testing offering; reagent ownership not asserted.',b,'commercial',roles=['commercial_partner'],typ='product',sub='diagnostics'))
co=dict(company_id='cmp_29387252-4b2c-4ce1-ae51-5af73001c707',products=products,evidence=[a,b,c,d],status='partial',coverage_note='Eighteen current clinical tests/panels. Partial: historical FoundationACT/earlier tissue/liquid tests, research-data platforms and discontinued MRD partnerships require review. Partner-performed assays linked as commercial partner; generic IHC targets are actual separately offered tests, not owned antibodies. Companion diagnostic drug labels not attributed as own medicines. FDA status differs between approved profiling tests and LDTs; no blanket approval claim.')
(out/'batch-0310.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
